package com.luxora.commerce.order.service;
import com.luxora.commerce.auth.security.AuthenticatedUser;import com.luxora.commerce.cart.service.CartService;import com.luxora.commerce.catalog.dto.PageResponse;import com.luxora.commerce.checkout.dto.CheckoutPreviewRequest;import com.luxora.commerce.checkout.service.*;import com.luxora.commerce.common.exception.NotFoundException;import com.luxora.commerce.order.dto.*;import com.luxora.commerce.order.model.*;import com.luxora.commerce.order.repository.OrderRepository;import com.luxora.commerce.promotion.service.PromotionService;import com.luxora.commerce.user.model.User;import com.luxora.commerce.user.repository.UserRepository;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.*;
@Service public class OrderService {private final CheckoutCalculationService calculator;private final OrderRepository orders;private final UserRepository users;private final CartService carts;private final OrderMapper mapper;private final PromotionService promotions;public OrderService(CheckoutCalculationService c,OrderRepository o,UserRepository u,CartService cart,OrderMapper m,PromotionService p){calculator=c;orders=o;users=u;carts=cart;mapper=m;promotions=p;}
@Transactional public OrderResponse createOrder(AuthenticatedUser user,CheckoutPreviewRequest request){CheckoutCalculation c=calculator.calculate(user.id(),request,true);User owner=users.getReferenceById(user.id());Order order=new Order(owner,c.shippingAddress(),c.subtotal(),c.shippingFee(),c.tax(),c.discount(),c.grandTotal(),c.currency(),c.promotion());for(CheckoutCalculationItem i:c.items()){i.variant().getInventoryItem().decrement(i.quantity());order.addItem(new OrderItem(i.productId(),i.variantId(),i.slug(),i.name(),variantName(i),i.sku(),i.color(),i.storage(),i.imageUrl(),i.unitPrice(),i.quantity(),i.lineTotal()));}promotions.consume(c.promotion());Order saved=orders.save(order);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){carts.clearAuthenticatedCart(user.id());}});return mapper.toResponse(saved);}
@Transactional(readOnly=true) public PageResponse<OrderSummaryResponse> listOrders(AuthenticatedUser u,int page,int size){Page<Order> p=orders.findPageByUserId(u.id(),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt")));List<UUID> ids=p.getContent().stream().map(Order::getId).toList();if(ids.isEmpty())return new PageResponse<>(List.of(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());Map<UUID,Order> loaded=orders.findAllWithItemsByUserIdAndIdIn(u.id(),ids).stream().collect(Collectors.toMap(Order::getId,Function.identity()));return new PageResponse<>(p.getContent().stream().map(o->loaded.getOrDefault(o.getId(),o)).map(mapper::toSummaryResponse).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
@Transactional(readOnly=true) public OrderResponse getOrder(AuthenticatedUser u,UUID id){return mapper.toResponse(orders.findByIdAndUserId(id,u.id()).orElseThrow(()->new NotFoundException("ORDER_NOT_FOUND","Order not found")));}private String variantName(CheckoutCalculationItem i){if(i.color()==null&&i.storage()==null)return i.sku();if(i.color()==null)return i.storage();if(i.storage()==null)return i.color();return i.color()+" / "+i.storage();}}